#include <map>
#include <stdexcept>
#include <string>

std::map<std::string, std::string> migrate(std::map<std::string, std::string> config, int fromVersion)
{
    if (fromVersion < 1 || fromVersion > 3) throw std::invalid_argument("unknown version");

    if (fromVersion == 1)
    {
        if (const auto it{ config.find("timeout") }; it != config.end())
        {
            const std::string& seconds{ it->second };
            if (seconds.empty() || seconds.find_first_not_of("0123456789") != std::string::npos)
                throw std::invalid_argument("timeout is not a whole number");
            config["timeout_ms"] = std::to_string(std::stoll(seconds) * 1000);
            config.erase("timeout");
        }
        config.erase("legacy_mode");
        if (const auto it{ config.find("verbose") }; it != config.end())
        {
            config["log_level"] = it->second == "true" ? "debug" : "info";
            config.erase("verbose");
        }
    }

    if (fromVersion <= 2)
    {
        if (const auto it{ config.find("log_level") }; it != config.end() && it->second == "warn")
            it->second = "warning";
        const auto host{ config.find("host") };
        const auto port{ config.find("port") };
        if (host != config.end() || port != config.end())
        {
            const std::string address{ (host != config.end() ? host->second : "localhost") + ":" + (port != config.end() ? port->second : "80") };
            config.erase("host");
            config.erase("port");
            config["address"] = address;
        }
        config.try_emplace("retries", "3");
    }

    config["version"] = "3";
    return config;
}

unitTests:
using Config = std::map<std::string, std::string>;
TEST("from version 1") {
    const Config v1{ { "timeout", "30" }, { "verbose", "true" }, { "legacy_mode", "on" }, { "host", "example.org" }, { "port", "8080" }, { "theme", "mocha" } };
    const Config expected{ { "timeout_ms", "30000" }, { "log_level", "debug" }, { "address", "example.org:8080" }, { "retries", "3" }, { "theme", "mocha" }, { "version", "3" } };
    CHECK(migrate(v1, 1) == expected);
}
TEST("verbose that is not true, and missing") {
    CHECK(migrate({ { "verbose", "yes" } }, 1) == (Config{ { "log_level", "info" }, { "retries", "3" }, { "version", "3" } }));
    CHECK(migrate({ { "verbose", "false" } }, 1).at("log_level") == "info");
    CHECK(migrate({}, 1) == (Config{ { "retries", "3" }, { "version", "3" } }));
}
TEST("from version 2") {
    const Config v2{ { "timeout_ms", "500" }, { "log_level", "warn" }, { "port", "9000" }, { "retries", "7" }, { "timeout", "keep me" } };
    const Config expected{ { "timeout_ms", "500" }, { "log_level", "warning" }, { "address", "localhost:9000" }, { "retries", "7" }, { "timeout", "keep me" }, { "version", "3" } };
    CHECK(migrate(v2, 2) == expected);
    CHECK(migrate({ { "host", "a.b" } }, 2).at("address") == "a.b:80");
    CHECK(migrate({ { "log_level", "error" } }, 2).at("log_level") == "error");
}
TEST("a warn level that came from version 1 stays as it was") {
    CHECK(migrate({ { "verbose", "true" }, { "log_level", "warn" } }, 1).at("log_level") == "debug");
}
TEST("from version 3") {
    const Config v3{ { "address", "x:1" }, { "log_level", "warn" }, { "version", "3" } };
    CHECK(migrate(v3, 3) == v3);
    CHECK(migrate({ { "host", "kept" } }, 3) == (Config{ { "host", "kept" }, { "version", "3" } }));
}
TEST("errors") {
    CHECK_THROWS_AS(migrate({}, 0), std::invalid_argument);
    CHECK_THROWS_AS(migrate({}, 4), std::invalid_argument);
    CHECK_THROWS_AS(migrate({ { "timeout", "1.5" } }, 1), std::invalid_argument);
    CHECK_THROWS_AS(migrate({ { "timeout", "" } }, 1), std::invalid_argument);
    CHECK_THROWS_AS(migrate({ { "timeout", "-3" } }, 1), std::invalid_argument);
    CHECK(migrate({ { "timeout", "0" } }, 1).at("timeout_ms") == "0");
}

